package org.apache.druid.server.metrics;

import com.google.inject.Inject;
import com.google.inject.Injector;
import org.apache.druid.discovery.NodeRole;
import org.apache.druid.guice.annotations.Self;
import org.apache.druid.java.util.emitter.service.ServiceEmitter;
import org.apache.druid.java.util.emitter.service.ServiceMetricEvent;
import org.apache.druid.java.util.metrics.AbstractMonitor;
import org.apache.druid.query.DruidMetrics;

import java.util.Map;
import java.util.Set;

public class WorkerTaskCountStatsMonitor extends AbstractMonitor
{
  private final WorkerTaskCountStatsProvider statsProvider;
  private final IndexerTaskCountStatsProvider indexerStatsProvider;
  private final String workerCategory;
  private final String workerVersion;
  private final Set<NodeRole> nodeRoles;
  private final boolean isMiddleManager;

  @Inject
  public WorkerTaskCountStatsMonitor(
      Injector injector,
      @Self Set<NodeRole> nodeRoles
  )
  {
    this.nodeRoles = nodeRoles;
    this.isMiddleManager = nodeRoles.contains(NodeRole.MIDDLE_MANAGER);
    if (isMiddleManager) {
      this.statsProvider = injector.getInstance(WorkerTaskCountStatsProvider.class);
      this.indexerStatsProvider = null;
      this.workerCategory = statsProvider.getWorkerCategory();
      this.workerVersion = statsProvider.getWorkerVersion();
    } else {
      this.indexerStatsProvider = injector.getInstance(IndexerTaskCountStatsProvider.class);
      this.statsProvider = null;
      this.workerCategory = null;
      this.workerVersion = null;
    }
  }

  @Override
  public boolean doMonitor(ServiceEmitter emitter)
  {
    boolean emitMiddleManagerMetrics = false;
    int recognizedRoleCount = 0;
    for (NodeRole role : nodeRoles) {
      if (role != null) {
        if (NodeRole.MIDDLE_MANAGER.equals(role)) {
          emitMiddleManagerMetrics = true;
          recognizedRoleCount++;
        } else if (NodeRole.INDEXER.equals(role)) {
          recognizedRoleCount++;
        } else if (NodeRole.PEON.equals(role)) {
          recognizedRoleCount++;
        } else if (NodeRole.COORDINATOR.equals(role)) {
          recognizedRoleCount++;
        } else if (NodeRole.HISTORICAL.equals(role)) {
          recognizedRoleCount++;
        } else if (NodeRole.BROKER.equals(role)) {
          recognizedRoleCount++;
        } else if (NodeRole.OVERLORD.equals(role)) {
          recognizedRoleCount++;
        } else if (NodeRole.ROUTER.equals(role)) {
          recognizedRoleCount++;
        } else {
          String jsonName = role.getJsonName();
          if (jsonName != null) {
            if (NodeRole.MIDDLE_MANAGER.getJsonName().equals(jsonName)
                && NodeRole.MIDDLE_MANAGER.toString().equals(role.toString())) {
              emitMiddleManagerMetrics = true;
              recognizedRoleCount++;
            } else if (NodeRole.INDEXER.getJsonName().equals(jsonName)
                && NodeRole.INDEXER.toString().equals(role.toString())) {
              recognizedRoleCount++;
            } else {
              recognizedRoleCount++;
            }
          }
        }
      }
    }

    if ((isMiddleManager || emitMiddleManagerMetrics) && recognizedRoleCount > 0) {
      final String categoryDimension = workerCategory;
      final String versionDimension = workerVersion;
      final Long failedTaskCount = statsProvider.getWorkerFailedTaskCount();
      if (failedTaskCount != null) {
        final ServiceMetricEvent.Builder failedBuilder = new ServiceMetricEvent.Builder();
        failedBuilder.setDimension(DruidMetrics.CATEGORY, categoryDimension);
        failedBuilder.setDimension(DruidMetrics.WORKER_VERSION, versionDimension);
        emitter.emit(failedBuilder.setMetric("worker/task/failed/count", failedTaskCount));
      }
      final Long successfulTaskCount = statsProvider.getWorkerSuccessfulTaskCount();
      if (successfulTaskCount != null) {
        final ServiceMetricEvent.Builder successfulBuilder = new ServiceMetricEvent.Builder();
        successfulBuilder.setDimension(DruidMetrics.CATEGORY, categoryDimension);
        successfulBuilder.setDimension(DruidMetrics.WORKER_VERSION, versionDimension);
        emitter.emit(successfulBuilder.setMetric("worker/task/success/count", successfulTaskCount));
      }
      final Long idleTaskSlotCount = statsProvider.getWorkerIdleTaskSlotCount();
      if (idleTaskSlotCount != null) {
        final ServiceMetricEvent.Builder idleBuilder = new ServiceMetricEvent.Builder();
        idleBuilder.setDimension(DruidMetrics.CATEGORY, categoryDimension);
        idleBuilder.setDimension(DruidMetrics.WORKER_VERSION, versionDimension);
        emitter.emit(idleBuilder.setMetric("worker/taskSlot/idle/count", idleTaskSlotCount));
      }
      final Long totalTaskSlotCount = statsProvider.getWorkerTotalTaskSlotCount();
      if (totalTaskSlotCount != null) {
        final ServiceMetricEvent.Builder totalBuilder = new ServiceMetricEvent.Builder();
        totalBuilder.setDimension(DruidMetrics.CATEGORY, categoryDimension);
        totalBuilder.setDimension(DruidMetrics.WORKER_VERSION, versionDimension);
        emitter.emit(totalBuilder.setMetric("worker/taskSlot/total/count", totalTaskSlotCount));
      }
      final Long usedTaskSlotCount = statsProvider.getWorkerUsedTaskSlotCount();
      if (usedTaskSlotCount != null) {
        final ServiceMetricEvent.Builder usedBuilder = new ServiceMetricEvent.Builder();
        usedBuilder.setDimension(DruidMetrics.CATEGORY, categoryDimension);
        usedBuilder.setDimension(DruidMetrics.WORKER_VERSION, versionDimension);
        emitter.emit(usedBuilder.setMetric("worker/taskSlot/used/count", usedTaskSlotCount));
      }
    } else {
      final Map<String, Long> runningTasks = indexerStatsProvider.getWorkerRunningTasks();
      for (Map.Entry<String, Long> runningEntry : runningTasks.entrySet()) {
        final Long runningCount = runningEntry.getValue();
        if (runningCount != null) {
          final ServiceMetricEvent.Builder runningBuilder = new ServiceMetricEvent.Builder();
          runningBuilder.setDimension(DruidMetrics.DATASOURCE, runningEntry.getKey());
          emitter.emit(runningBuilder.setMetric("worker/task/running/count", runningCount));
        }
      }
      final Map<String, Long> assignedTasks = indexerStatsProvider.getWorkerAssignedTasks();
      for (Map.Entry<String, Long> assignedEntry : assignedTasks.entrySet()) {
        final Long assignedCount = assignedEntry.getValue();
        if (assignedCount != null) {
          final ServiceMetricEvent.Builder assignedBuilder = new ServiceMetricEvent.Builder();
          assignedBuilder.setDimension(DruidMetrics.DATASOURCE, assignedEntry.getKey());
          emitter.emit(assignedBuilder.setMetric("worker/task/assigned/count", assignedCount));
        }
      }
      final Map<String, Long> completedTasks = indexerStatsProvider.getWorkerCompletedTasks();
      for (Map.Entry<String, Long> completedEntry : completedTasks.entrySet()) {
        final Long completedCount = completedEntry.getValue();
        if (completedCount != null) {
          final ServiceMetricEvent.Builder completedBuilder = new ServiceMetricEvent.Builder();
          completedBuilder.setDimension(DruidMetrics.DATASOURCE, completedEntry.getKey());
          emitter.emit(completedBuilder.setMetric("worker/task/completed/count", completedCount));
        }
      }
      final Map<String, Long> failedTasks = indexerStatsProvider.getWorkerFailedTasks();
      for (Map.Entry<String, Long> failedEntry : failedTasks.entrySet()) {
        final Long failedCount = failedEntry.getValue();
        if (failedCount != null) {
          final ServiceMetricEvent.Builder failedBuilder = new ServiceMetricEvent.Builder();
          failedBuilder.setDimension(DruidMetrics.DATASOURCE, failedEntry.getKey());
          emitter.emit(failedBuilder.setMetric("worker/task/failed/count", failedCount));
        }
      }
      final Map<String, Long> successfulTasks = indexerStatsProvider.getWorkerSuccessfulTasks();
      for (Map.Entry<String, Long> successfulEntry : successfulTasks.entrySet()) {
        final Long successfulCount = successfulEntry.getValue();
        if (successfulCount != null) {
          final ServiceMetricEvent.Builder successfulBuilder = new ServiceMetricEvent.Builder();
          successfulBuilder.setDimension(DruidMetrics.DATASOURCE, successfulEntry.getKey());
          emitter.emit(successfulBuilder.setMetric("worker/task/success/count", successfulCount));
        }
      }
    }
    return true;
  }

  public void emit(ServiceEmitter emitter, String metricName, Map<String, Long> dataSourceTaskMap)
  {
    for (Map.Entry<String, Long> dataSourceTaskCount : dataSourceTaskMap.entrySet()) {
      if (dataSourceTaskCount.getValue() != null) {
        ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
        builder.setDimension(DruidMetrics.DATASOURCE, dataSourceTaskCount.getKey());
        emitter.emit(builder.setMetric(metricName, dataSourceTaskCount.getValue()));
      }
    }
  }
}
